// FUNCTION: BFME2 0x00482EFF size=40 name=?calcSleepTime@PoisonedBehavior@@IAE?AW4UpdateSleepTime@@XZ evidence=N:ledger
UpdateSleepTime PoisonedBehavior::calcSleepTime()
{
	UnsignedInt currentFrame = TheGameLogic->getFrame();
	if (m_poisonOverallStopFrame == 0 || m_poisonOverallStopFrame == currentFrame)
		return UPDATE_SLEEP_FOREVER;
	return frameToSleepTime(m_poisonDamageFrame, m_poisonOverallStopFrame,
		UPDATE_SLEEP_FOREVER, UPDATE_SLEEP_FOREVER);
}

