// FUNCTION: BFME2 0x00482F7D size=120 name=??0PoisonedBehavior@@QAE@PAVThing@@PBVModuleData@@@Z evidence=N:ledger
PoisonedBehavior::PoisonedBehavior(Thing *thing, const ModuleData *moduleData)
	: UpdateModule(thing, moduleData)
	, m_poisonDamageFrame(0)
	, m_poisonOverallStopFrame(0)
	, m_poisonDamageAmount(0.0f)
	, m_deathType(5)
{
	setWakeFrame(getObject(), UPDATE_SLEEP_FOREVER);
}

static const UnsignedInt &pbMinFrame(const UnsignedInt &a, const UnsignedInt &b)
{
	return a < b ? a : b;
}

// FUNCTION: BFME2 0x00483011 size=114 name=?startPoisonedEffects@PoisonedBehavior@@IAEXPBVDamageInfo@@@Z evidence=N:ledger
void PoisonedBehavior::startPoisonedEffects(const DamageInfo *damageInfo)
{
	const PoisonedBehaviorModuleData *data = getPoisonedBehaviorModuleData();
	UnsignedInt currentFrame = TheGameLogic->getFrame();
	m_poisonDamageAmount = damageInfo->out.m_actualDamageDealt;
	m_poisonOverallStopFrame = currentFrame + data->m_poisonDuration;
	if (m_poisonDamageFrame != 0)
		m_poisonDamageFrame = pbMinFrame(m_poisonDamageFrame, currentFrame + data->m_poisonDamageInterval);
	else
		m_poisonDamageFrame = currentFrame + data->m_poisonDamageInterval;
	m_deathType = damageInfo->in.m_deathType;
	Drawable *draw = getObject()->getDrawable();
	if (draw)
		draw->setTintStatus(1 << 2);
	setWakeFrame(getObject(), calcSleepTime());
}

// FUNCTION: BFME2 0x00483083 size=38 name=?rva00483083@PoisonedBehavior@@QAEXXZ evidence=?:placeholder
void PoisonedBehavior::stopPoisonedEffects()
{
	m_poisonDamageFrame = 0;
	m_poisonOverallStopFrame = 0;
	m_poisonDamageAmount = 0.0f;
	Drawable *draw = getObject()->getDrawable();
	if (draw)
		draw->clearTintStatus(4);
}

// FUNCTION: BFME2 0x004830A9 size=82 name=?xfer@PoisonedBehavior@@MAEXPAVXfer@@@Z evidence=N:ledger
void XferDeathType(Xfer *xfer, Int *value);

void PoisonedBehavior::xfer(Xfer *xfer)
{
	UpdateModule::xfer(xfer);
	if (xfer->IsLightCRC())
		return;
	xfer->Version1();
	*xfer == m_poisonDamageFrame;
	*xfer == m_poisonOverallStopFrame;
	*xfer == m_poisonDamageAmount;
	XferDeathType(xfer, &m_deathType);
}

// FUNCTION: BFME2 0x004830FB size=22 name=?onDamage@PoisonedBehavior@@UAEXPAVDamageInfo@@@Z evidence=N:ledger
void PoisonedBehavior::onDamage(DamageInfo *damageInfo)
{
	if (damageInfo->in.m_damageType == DAMAGE_POISON)
		startPoisonedEffects(damageInfo);
}

// FUNCTION: BFME2 0x00483111 size=34 name=?onHealing@PoisonedBehavior@@UAEXPAVDamageInfo@@@Z evidence=N:ledger
void PoisonedBehavior::onHealing(DamageInfo *damageInfo)
{
	stopPoisonedEffects();
	setWakeFrame(getObject(), UPDATE_SLEEP_FOREVER);
}

// FUNCTION: BFME2 0x00483133 size=152 name=?update@PoisonedBehavior@@UAE?AW4UpdateSleepTime@@XZ evidence=N:ledger
UpdateSleepTime PoisonedBehavior::update()
{
	const PoisonedBehaviorModuleData *d = getPoisonedBehaviorModuleData();
	UnsignedInt currentFrame = TheGameLogic->getFrame();
	if (m_poisonOverallStopFrame == 0)
		return UPDATE_SLEEP_FOREVER;

	if (m_poisonDamageFrame != 0 && currentFrame >= m_poisonDamageFrame)
	{
		Rva00263895Member damageRecord;
		DamageInfo *damage = (DamageInfo *)&damageRecord;
		damage->in.m_amount = m_poisonDamageAmount;
		damage->in.m_sourceID = INVALID_ID;
		damage->in.m_damageType = DAMAGE_UNRESISTABLE;
		damage->in.m_damageFXOverride = DAMAGEFX_POISON;
		damage->in.m_deathType = (DeathType)m_deathType;
		getObject()->attemptDamage(damage);
		m_poisonDamageFrame = currentFrame + d->m_poisonDamageInterval;
	}

	if (m_poisonOverallStopFrame != 0 && currentFrame >= m_poisonOverallStopFrame && !getObject()->isEffectivelyDead())
		stopPoisonedEffects();

	return calcSleepTime();
}
